                    sqlQuery = $" insert into POI_TEXT (id, poi_id, descrizione, lingua_id, attivo, mod_dte, uuid) values (22, 22, 'Un tempo Borgiano era un castello murato, oggi è un piccolo paesino con case sparse lungo il declivio sud orientale del monte Letegge. È separato dal capoluogo comunale (Serrapetrona) dal grande solco del Fosso della Valle.\nLe terre di Borgiano sono territori fertili per la crescita copiosa di vigneti, da cui origina la tipica Vernaccia di Serrapetrona.\n',  1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
