                    sqlQuery = $" insert into POI_TEXT (id, poi_id, descrizione, lingua_id, attivo, mod_dte, uuid) values (27, 27, 'bla bla bla bla bla bla',  1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $" insert into POI_TEXT (id, poi_id, descrizione, lingua_id, attivo, mod_dte, uuid) values (28, 28, 'Serrapetrona è situata sulla destra del torrente Cesolone, in un territorio ricco di boschi di querce, lecci, noccioli, carpini paesaggisticamente interessante. Su questi terreni, prevalentemente montuosi e collinari, si produce la “Vernaccia di Serrapetrona D.O.C.G.” nata dalla passione di alcuni vitivinicoltori della zona, un vino spumante apprezzato a livello nazionale. Il borgo è munito di due cinte murarie medievali con quattro massicce porte.',  1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $" insert into POI_TEXT (id, poi_id, descrizione, lingua_id, attivo, mod_dte, uuid) values (29, 29, 'Matelica è posta a 354 m s.l.m., nella vallata del fiume Esino, unica valle marchigiana che si sviluppa — almeno parzialmente — da nord a sud. Il territorio è in prevalenza collinare, con le montagne che la costeggiano ai lati della valle, tra cui il monte San Vicino.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $" insert into POI_TEXT (id, poi_id, descrizione, lingua_id, attivo, mod_dte, uuid) values (30, 30, 'Caldarola (Cardaròla in dialetto maceratese) è un comune italiano di 1601 abitanti della provincia di Macerata, nelle Marche.Il paese è risultato fortemente danneggiato dalla sequenza sismica del 2016/17 Amatrice - Norcia - Visso, soprattutto dalle scosse del 26 ottobre e del 30 ottobre 2016, che hanno rovinato in maniera irreparabile gran parte del patrimonio storico e gli edifici scolastici.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();



                    sqlQuery = $" insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2005402, 2005402, 'Un’altra chiesa molto importante, situata nella parte più alta del paese, con un altro campanile, ma totalmente diversa, e con un gioiello liberty all’interno.', 'Fu fatta costruire dal Cardinale Evangelista Pallotta nei primi anni del ‘600 forse sulle stesse rovine della chiesa di San Gregorio della Vigna fondata dai Longobardi verso la fine del 700. La costruzione è a croce latina, il soffitto a capriate. L’altare di legno massiccio fu donato nel 1638 dal Cardinale Giovan Battista Pallotta e l’arciprete" +
                        $" Carlo Benedetti nel 1690 provvide a dorarlo ed argentarlo. Ai lati dell’altare si trovano il cenotafio di Varino Favorino e la tomba di Ludovico Clodio. La pala dell’altare rappresenta i Santi Gregorio e Valentino cui è dedicata la chiesa, con al centro due apostoli. La cappella di sinistra conserva la Madonna del Rosario (olio su tela) con i Santi Francesco e Domenico. La parte superiore è di Andrea de Magistris mentre i due Santi così vigorosi e lotteschi sono di Durante Nobili. Sempre in questa cappella gli affreschi del Misteri del Rosario (1918) sono di Augusto Mussini (Fra Paolo). Come altre volte, il pittore si trasformò in poeta. " +
                        $"Rappresentano uno dei pochi esempi al mondo di arte Liberty a tema religioso. Lo schema decorativo dei Misteri Dolorosi, Gaudiosi e Gloriosi, è costituito da fasci di rose che, da otto antichi vasi posti a d a due alle basi degli angoli, salgono al soffitto, girano sugli archi e si ricongiungono a ghirlanda sorretti da quattro angeli e dai festoni si dilatano su un cielo luminoso frastagliato da candide nubi. I Misteri Dolorosi in basso sullo stilobate, sono simboleggiati da un fregio di figure terrene e celesti che esprimono dolore nella tonalità rossa che richiama il sangue della passione. I Misteri Gaudiosi sono simboleggiati dal giallo " +
                        $"ove s’immergono figure di Angeli vaganti nel cielo, sempre più incorporei. I Misteri Gloriosi sono ridati da una visione luminosa con una miriade di putti dai movimenti arditi e dai visi sorridenti che esprimono la Gloria dei Cieli.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                        dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2007316, 2007316, 'Lungo il percorso Francescano della Marca, con deviazione a monte del Santuario della Madonna del Sasso, troviamo i ruderi dell’ “Abbatia Sancti Benedicti de Crypta Saxi Latronis”.', 'A monte della frazione di Bistocco troviamo i resti dell’Abbazia Sancti Latronis de cripta saxi, i cui monaci intorno al 1000 d.c. avevano giurisdizione sull’abitato sottostante. Il monastero benedettino che  risale   al  Xi-X secolo, è normalmente fortificato e di difficile accesso,  mimetizzato nel bosco e nel colore della roccia, si " +
                        $"caratterizza come edificio chiuso ed attualmente ci mostra parte della torre ed alcune cortine della chiesa con portale a tutto sesto ed una monofora. Nel particolare dei ruderi si può comprendere come il manufatto è una vera e propria fortificazione feudale posta ai confini dell’area d’influenza monastica con quella dello stato camerte, pronta a raccogliere al suo interno monaci e popolazione locale nei momenti di pericolo. Oltre a ciò essa svolgeva le normali funzioni di centro propulsore della vita sociale e spirituale delle genti autoctone, raccolte nelle varie corti dipendenti.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018891, 2018891, 'Un’altra chiesa situata in Piazza e costruita nel XVIII secolo, con una cupola poligonale e interni a croce greca, con alcune opere molto importanti e un quadro protagonista.', 'Il santuario chiude il lato sud-ovest della piazza e sorge sullo spazio ricavato dalla demolizione di una precedente chiesa del 400, l’edificio progettato dell’architetto Augustoni venne aperto al culto nel 1780. La facciata si sviluppa su due piani divisi da una travatura aggettante. La porta principale con timpano è incorniciata da quattro lesene sulle quali " +
$"poggia una trabeazione; ai lati due nicchie. Stesso motivo per la parte superiore. LA cupola con lanterna è di forma poligonale, il campanile riprende i motivi della facciata. L’interno è a croce greca; la cupola raccordata da quattro pennacchi dà armonia e luce al complesso. Dodici porte che simboleggiano i dodici Apostoli, scandiscono gli spazi in basso, ma successive modifiche hanno alterato la primitiva struttura. Dietro l’altare maggiore si apre una nicchia nella quale si trova il quadro di Lorenzo d’Alessandro coperto in parte da un’ostia e da angeli volanti. Nella tela sopra l’altare di destra (olio su tela, cm. 120x280 – San Pietro battezza il Centurione)" +
$" +) la scena si svolge in una cella nella cui penombra le figure acquistano rilievo per mezzo degli effetti di luce provenienti dalla finestra e dall’apparizione dello Spirito Santo. Sopra l’altare di sinistra è posto un crocifisso ligneo del XVII sec. Secondo la tradizione fu donato alla confraternita nel 1666 da un pellegrino che ammalatosi venne ricoverato nell’ospedale ove poco dopo morì. Lungo le pareti in alto, 10 tele (cm. 150x60) raffigurano storie della vita della Vergine. Alla stessa altezza ed a fianco degli altari laterali, 4 santi (cm 80x50)." +
$"Tutto il complesso, ispirato alla cultura umbra su modelli cinquecenteschi, è di notevole livello.Nelle tele più grandi si fa apprezzare l’abilità del comporre scene affollate di figure; nelle altre, invece, si fa apprezzare una maggiore freschezza e scioltezza di pennellata.In sacrestia si trova un grosso armadio in noce del 700 con quattro cassetti e maniglie in ferro. " +
$"Il quadro “Madonna del Monte” fu commissionato dal Beato Francesco e fu eseguito nel 1491, una lunga benda porta questa scritta: “Sub ergo Maria confraternitate sue idem esse tego”. Le parole non danno un vero senso compiuto ma probabilmente stavano a significare un’invocazione di protezione.Sul fondo di oro finissimo si staglia la figura della vergine che regge con il braccio destro il figlio benedicente, un velo bianco incornicia il volto ovale della Vergine, prolungandosi con un lembo fino al petto. Il manto turchino foderato di verde copre tutta la persona riunendosi sulle ginocchia; la veste rossa si dispiega a cannelli con naturalezza.La veste giallognola " +
                        $"ed i capelli biondi del figlio completano coloristicamente la figurazione principale intorno alla quale vi sono quattro gruppi di due santi ciascuno.Si possono riconoscere: San Pietro, San Giovanni Battista, San Domenico e San Rocco. Il volto della Vergine unisce negli occhi una maestà che impone ed una bontà che intenerisce. Davanti alle ginocchia della Madonna due grandi tavole sostenute da San Francesco, Sant’Antonio da Padova, San Martino, San Gregorio disciplinati e gentiluomini dell’epoca.Sulla tavola di sinistra è raffigurata, tra l’altro, la Caldarola dell’epoca cinta di mura, una cassa chiusa con la scritta “conserva” ed una tazza " +
                        $"piena di monete. Sull’altra tavola sono alcuni confratelli e consorelle in ginocchio, una cassa con la solita scritta ed una con le parole “Mons Virginis”. Tutta la figurazione sintetizza l’opera del committente che, attraverso una confraternita a scopo religioso e caritativo mirava al benessere materiale e spirituale del paese, mettendo tutto sotto la protezione della Vergine.Una leggenda racconta che il Beato Francesco sognò la visione dei volti della Vergine e del Figlio; ma non riuscendo l’artista a riprodurli come Francesco voleva fu pregato dal Beato di confessarsi e comunicarsi. Al mattino seguente i volti furono ritrovati ritoccati da " +
                        $"mano angelica.L’immagine fu incoronata nel 1814 da Pio VII.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{ Guid.NewGuid()}" +
                    $"') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018892, 2018892, 'Un gioiello mozzafiato all’interno del Palazzo Pallotta. Una stanzina totalmente affrescata, vieni a conoscere la sua storia!', 'Così denominata per le scene raffigurate dagli affreschi, dedicate all’arte venatoria (paradisòs in greco indica appunto il giardino, il luogo di caccia); questa stanza è un piccolo gioiello incastonato nel Palazzo comunale, quasi nascosto e remoto, luogo di meditazione del Cardinale dove la realtà si sublima nella favola attraverso un paesaggio altamente lirico, che rappresenta una flora e una fauna esotiche e scene di " +
$"caccia animate da cavalli impennati, levrieri, cacciatori…" +
$"Sino ad oggi di questa stanza non esiste un documento storico nè un’analisi critica.Gli storici caldarolesi l’attribuiscono a Simone de Magistris; nonostante i fitti richiami ad altre sue opere e la riconosciuta capacità di trasferire la realtà nel mondo lirico della favola, i critici pensano che l’opera appartenga ad altra mano; probabilmente il card.Evangelista Pallotta si portò da Roma un pittore di grido e di facile comprensione. Caduto l’intonaco da una parte, restano le altre tre ed il soffitto con cacciatori, cinghiali, volatili, orsi, tori. Il paesaggio, la flora e la fauna sono esotici." +
$"I pannelli, incorniciati, sono separati da putti nudi; in alto le cornici sono coperti di festoni.Nello stanzino il movimento diventa slancio, i colori vivi, la narrazione quasi agitata.I personaggi sono deliziosi ed indefiniti, i colori rifrangono ore immacolate. I quadri del soffitto si rifugiano nel mitico e nell’emblema.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{ Guid.NewGuid()} " +
                    $"')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018893, 2018893, 'La chiesa principale, costruita nel 1590, con il suo campanile che guarda dall’alto l’intera città. Entra e scopri gli incredibili dipinti di Simone de Magistris.', 'Fu inaugurata nel 1590 con bolla di Sisto V che la elevò a collegiata insigne ed il cui stemma domina la facciata vicino a quello del cardinal Evangelista Pallotta. Il campanile cuspidato alto 45 metri, è opera dell’architetto Pompeo Floriani. La facciata si eleva su due piani nettamente separati. Nel piano inferiore si notano l’ampia apertura della porta, sormontata da un timpano arrotondato " +
$"e due nicchie per lato. Il piano superiore ripete la parte centrale con un finestrone in mezzo e due nicchie ai lati. All’interno la chiesa è a tre navate con coro; in ognuna delle navate laterali sono disposte tre cappelle. Sulla parete di fondo del coro si erge il complesso monumentale dell’Altare Maggiore, incorniciato da due imponenti colonne scanalate con capitello corinzio che, secondo la leggenda, sono state portate a Roma dal tempio di Gerusalemme e quindi fatte trasportare a Caldarola dal Cardinale Evangelista Pallotta. Sulle pareti del presbiterio una copia della Vergine id Foligno del Raffaello contrapposta alla grande tela della crocefissione da attribuire a Guido Reni. " +
$"Al centro della grande tela (mt. 3,50 x 2,00) incorniciata, opera di Simone de Magistris (1594). La tela è denominata “La Messa di San Martino” o “Transito di San Martino”. La complessa macchina narrativa messa in atto da Simone de Magistris per la pala di San Martino ha origine dall’intensità della preghiera del committente, il cardinale che, rivolti gli occhi al cielo, condivide la stessa visione si San Severino, vescovo di Colonia: l’accoglimento dell’anima di San Martino in paradiso. La stessa immagine è oggetto del sogno di Sant’Ambrogio che, come riferisce la Legenda Aurea, addormentatosi durante la celebrazione della messa, partecipò ai funerali del Santo. Nello sfondo a sinistra " +
$"il pittore descrive la morte di Martino circondato dai frati. Iniziando la visita a destra, nella prima cappella si trova un crocifisso ligneo del XVI sec.; nella seconda la reliquia di San Destro e una tela raffigurante Sant’Emio. Nella terza una pregevole opera di Giovanni Andrea de Magistris, padre di Simone, firmata e datata 1537, raffigurante la Madonna del Carmelo con i Santi Giuseppe e Girolamo. Nella navata sinistra, la prima cappella è quella della fonte battesimale realizzata in pietra gessara; la cappella centrale è chiusa da una cancellata in ferro battuto e contiene un tabernacolo in legno dorato datato 1595, attribuito a Desiderio Bonfini di Montalto Marche, con ai lati " +
$"le statue lignee di San Sebastiano e dell’evangelista Luca /sec XVI); l’ultima cappella è dedicata a San Michele Arcangelo. Ai lati dell’ingresso due tele: Sant’Anna (a sinistra) ed il Beato Francesco Piani (a destra) con raffigurato il paese di Caldarola. Nella sacrestia, una stanza di notevoli dimensioni con pavimento di quadrotti di cotto antichi e soffitto in legno decorato, si trova la tela di Durante Nobili, firmata e datata 1535, raffigurante la Madonna con i Santi Cosma e Damiano. L’opera realizzata quando il pittore aveva appena 17 anni ed era allievo di Lorenzo Lotto, presenta una marcata influenza e probabilmente un intervento diretto del Maestro.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018894, 2018894, 'Il Palazzo Pallotta di Caldarola, situato in Piazza Vittorio Emanuele II, è un elegante esempio di architettura rinascimentale. Costruito nel XVI secolo, presenta una facciata imponente e interni riccamente decorati. \nLa “Stanza del Paradiso”, contenuta al suo interno, rappresenta uno dei gioielli artistici del paese.', 'Il palazzo che domina la piazza principale, sede del municipio e cuore della città. All’interno troviamo la pinacoteca comunale, il gioiello della stanza del paradiso, ed un piano Nobile solitamente adibito a mostre data la perfetta conservazione degli affreschi e la recente ristrutturazione." +
                        $"Il palazzo pallotta oggi sede del Municipio, sorge al centro di Caldarola e forma insieme alla chiesa collegiata di San Martino un complesso edilizio di grande rilievo; nel suo impianto architettonico è disegnata la piazza antistante, probabilmente concepita con progetto unitario per essere chiusa su tre lati da edifici porticati, come fa pensare l’affresco che si trova nella Sala del Consiglio(detta Salone dei Cardinali Pallotta). L’importanza storica del palazzo sta anche nella sua architettura rigorosamente " +
                        $"aderente ai principi della Controriforma.Concepito e realizzato in tempi brevi e in modo estremamente unitario, ha subito nel tempo pochissime aggiunte e trasformazioni, per cui può essere considerato un chiaro esempio di uno degli sviluppi manieristici dell’architettura del Rinascimento.L’intera vicenda edilizia del palazzo e tutto il suo valore storico, sono imperniati intorno ai due personaggi caldarolesi: il cardinale Evangelista Pallotta e il pittore Simone de Magistris. Gli affreschi del piano nobile e i " +
                        $"soffitti a cassettoni costituiscono un complesso di grande rilievo non solo per la loro mole, ma anche per la qualità delle pitture. All’interno troviamo LA Stanza del Paradiso, cosi denominata per le scene raffigurate dagli affreschi, dedicate all’arte venatoria(paradisòs in greco indica appunto il giardino, il luogo di caccia); questa stanza è un piccolo gioiello incastonato all’interno del palazzo comunale, quasi nascosto e remoto, luogo di meditazione del Cardinale, là dove la realtà si sublima nella favola attraverso " +
                        $"un paesaggio altamente lirico, che rappresenta una flora ed una fauna esotiche e scene di caccia animate da cavalli impennati, levrieri, cacciatori… \n" +
                        $"Gli storici caldarolesi l’attribuiscono a Simone de Magistris; nonostante i fitti richiami ad altre sue opere e la riconosciuta capacità di trasferire la realtà nel mondo lirico della favola, i critici pensano che l’opera sia da attribuire a Domenico Malpiedi e Antonio Tempesta. Caduto l’intonaco da una parete, restano le altre tre ed il soffitto. I pannelli, incorniciati, sono separata da putti nudi; in alto le cornici sono coperte di festoni.Nello stanzino il movimento diventa slancio, i colori vivi, la narrazione quasi agitata.I personaggi sono deliziosi e indefiniti, i colori rifrangono ore immacolate. I quadri del soffitto si rifugiano nel mitico e nell’emblema.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{ Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018895, 2018895, 'Incastonato tra la natura sopra la frazione di Valcimarra, questa piccola chiesa che sembra intagliata nella montagna vi lascerà senza parole.', 'Il santuario nasconde, secondo la leggenda, l’antro della Sibilla Cimaria; annesso alla chiesa vi è un romitorio. Al secondo ‘400 appartengono i due affreschi dell’interno: la Crocifissione e Madonna con Bambino. L’affresco relativo alla crocifissione fa pensare ad un pittore anonimo noto come il Maestro di Patullo.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery =$"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018896, 2018896, 'L’unica chiesa di Pievefavera, in stile barocco, con 4 cappelle e decorazioni medievali. È stata modificata molte volte ed è un chiaro esempio della storia di questo piccolo borgo.', 'La chiesa, eretta nel XII secolo, è stata molto rimaneggiata; la facciata presenta un portale a tutto sesto con decorazioni altomedievali. L’interno di gusto barocco si presenta a sala unica con quattro cappelle laterali ed un imponente altare centrale." +
                    $"Dell’ antico impianto rimane solo l’abside dietro l’altare centrale.Opera pregevole è il San Sebastiano ligneo cinquecentesco.La canonica è accostata alla chiesa seguendo l’andamento del terreno e formando così il sagrato di forma triangolare.Alla fine del XIII secolo è stata costruita la zona che circonda il sagrato mentre il fabbricato adiacente la chiesa risale al XIV sec.Attualmente sul sagrato sono riportati alcuni reperti archeologici in modo da costituire un “antiquarium” all’aperto.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{ Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018899, 2018899, 'Situato sopra un colle, il Castello di Caldarola si impone di una costruzione in stile rinascimentale creando un suggestivo quadro d’insieme dl sapore fiabesco.', 'Il Castello subì una modifica radicale verso la fine del ‘500, quando il Cardinale Evangelista Pallotta lo trasformò in una residenza estiva. Nel 1862 il conte Giuseppe abbellì la reggia, in particolare il giardino seguendo lo stile rinascimentale. Nel 1885 il conte Desiderio fece dei lavori di restauro, in particolare il cassero, la torre nord, la mercatura guelfa, il ponte levatoio ed i camini di" +
                    $" ronda, dove tutt’ora sono presenti all’interno della struttura. È anche presente, all’interno del castello, una sala carrozze, delle sellerie e delle armi; nelle stanze reali sono presenti anche delle opere d’arte su tela, sculture, affreschi, arredi dell’epoca e le testimonianze dei personaggi illustri, che nel corso dei secoli hanno visitato Caldarola. Tra le visite più importanti occorre ricordare il pontefice Clemente VIII, venuto al castello nel 1598, il Cardinale Casimirro nel 1644 ed infine, fu ospite anche Cristina di Svezia, nonché futura regina di Polonia, nel 1666. " +
                    $"Le biblioteche, un archivio recentemente riordinato e le numerose collezioni documentano le vicende della nobile famiglia nell’evolversi dei secoli. " +
                    $"Lo stemma della famiglia Pallotta non è altro che un flagello a palle snodate, la famosa arma, che Guglielmo Pallotta utilizzò nella battaglia del 1296, per difendere la fortezza dagli attacchi dei francesi.Molto importante è la cappellina arredata con arredi sacri dell’epoca.Di notevole rilevanza è la presenza di un “trumeau” d’arte marchigiana del 1600, posto nella stanza da letto reale.Verso la metà del secolo scorso, il conte Giuseppe fece costruire, con gusto rinascimentale, un cortile dove sopra un muretto vi sono i busti di Dante, Petrarca, Tasso e Ariosto.Infine nella torre d’angolo alla sinistra di Porta Camerte vi sono due lapidi che riportano la bolla papale di Eugenio IV dove vede " +
                    $"passare il potere dai Maurizi al loro congiunto Jacopo Pallotta, che al tempo era capitano ed architetto militare discente dal noto condottiero Guglielmo da Messina.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{ Guid.NewGuid()}" +
                    $"')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018900, 2018900, 'La fortificazione è varanesca e difendeva il lato Sud e Est del colle. La cortina di levante è la più gigantesca dei castelli della zona.', 'E` cerniera alle due cortine, la torre poligonale trasformata poi in campanile.Ha soffitto a capriate e cinque altari in legno dorato con colonne che incorniciano le tele.Tra il `400 ed il `500 si riempì di suppellettili di gran gusto.Nobile da Lucca lasciò qui il grosso del suo repertorio.Andrea De Magistris affrescò la Santa Lucia nella nicchia di sinistra e la Madre con Bambino nella " +
                    $"parete di fondo.Simone De Magistris dipinse i santi Antonio e Venanzio, a sinistra del presbiterio, mentre gli affreschi nelle nicchie sono attribuiti a Federico De Magistris.Annibale Mancini ai primi del `600 firmò la tela con la Vergine e Santi, sotto la cantoria. Nella sacrestia è conservato un ciborio a muro che poteva far parte della cappellina castellare. Di notevole interesse il Cristo Morto del 1400, posto sotto l`altare, ed il rude e maestoso Sant`Antonio Abate.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018901, 2018901, 'Nel 1263 i Varano ottennero il diritto di giurisdizione ecclesiastica e civile sul “castrum plebis de Faveria” e lo mantennero fino al Concilio di Trento con una breve interruzione dal 1434 al 1443.', '', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018903, 2018903, 'Museo', 'Una storia che oggi è visibile all`interno del torrione esagonale adiacente alla chiesa di Pievefavera.Da ricordare due capitelli: uno barbarico, protoromanico, sfaccetato in rigida geometria; ha gli spigoli smussati con decorazioni a lancia. L`altro, di pietra chiara a tronco di piramide, ha le quattro facce scolpite a bassorilievo. Possiamo catalogarlo come pulvino o capitello a staffadi chiara impostazione bizantina. Da menzionare anche una tomba romana chiusa a capanna da embrici, copertura composta da sei a otto grandi terrecotte, secondo la lunghezza della salma, comunemente chiamate tombe a cassa.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018904, 2018904, 'Il Museo Civico di Caldarola comprende la Pinacoteca della Resistenza, una sezione dedicata alla Caldarola Sistina e sale per esposizioni temporanee.', 'Il duplice aspetto del museo di arte contemporanea è nato dagli incontri interlocutori e programmatici che hanno preceduto il suo assetto poiché è sembrato giusto agli organizzatori promuovere, oltre alla presenza del notevole nucleo espositivo già entrato a far parte del patrimonio istituzionale e prevalentemente di carattere retrospettivo in un legame anche cronologico con la tematica proposta, una situazione in divenire di opere attuali afferenti al soggetto pur nella diversità dei tempi e delle intenzioni che la determineranno. Le cronache culturali devono poter assumere questa presa di posizione, in qualche modo scomoda ma indubbiamente responsabile. Sono considerazioni valevoli per chi è ancora diffidente verso un rigoroso ordine di idee e di fatti maturato nel secondo ‘900 sulle fondamenta di una forte tradizione storica e culturale, soprattutto di significazione collettiva.', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018905, 2018905, 'Nell’antico borgo medioevale di Vestignano, immerso nel verde dei monti Sibillini, si trova il piccolo museo privato di Arte Povera Contadina “Luigi Fagianella” fondato nell’agosto del 2006 dai coniugi Aurora e Betto Sclavi.', '', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}')";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018907, 2018907, 'Esercizio pubblico', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018909, 2018909, 'L’hotel è stato interamente ristrutturato nel 2018 e dispone di 11 camere.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018910, 2018910, '**Attività temporaneamente sospesa causa sisma**', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018912, 2018912, '**Attività temporaneamente sospesa causa sisma**', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018913, 2018913, 'Un piccolo bar di paese, situato prima del corso caldarolese, al termine di un bel viale di Tigli che fa da antipasto al centro storico.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018914, 2018914, 'Chiosco bar, bibite, panini', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018916, 2018916, 'Una grandissima villa immersa nelle colline tra Caldarola e Belforte molto bella ed ordinata, ideale per qualsiasi tipo di occasione, sia per il semplice pranzo di lavoro, che per cerimonie.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018917, 2018917, 'Pizza in Piazza nasce nel marzo 2013 nella piazza Vittorio Emanuele II di Caldarola, un piccolo paese nell’entroterra Maceratese.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018918, 2018918, 'L’agriturismo si propone come un luogo tranquillo, che offre agli utenti la possibilità di  rilassarsi immersi nella natura, senza privarli e far loro mancare  tutti i comfort più moderni.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018919, 2018919, 'L’agriturismo nasce nell’Ottocento dal desiderio di un padre di famiglia, ormai anziano, che anziché riposare e godersi l’anzianità, cercava  sempre qualcosa da fare.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018920, 2018920, 'Bea Villa Bea è un B&amp;B di recente ristrutturazione, circondato dalle colline ed immerso nel verde.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018921, 2018921, 'Si realizzano lavorazioni artigianali di pasticceria, gelateria, pizzeria e panificazione.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018922, 2018922, 'Le Case Vacanze di proprietà di Dibiagi Fausto sono situate nello splendido medioevale borgo di “Pievefavera” in una posizione panoramica e per la tranquillità del luogo consentono agli ospiti momenti di relax e benessere.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
                    dbcmd.ExecuteNonQuery();
                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018923, 2018923, 'Situato a Caldarola, a 33 km da Macerata, il Mazzamurello offre una piscina stagionale all’aperto e la connessione WiFi gratuita.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
                    dbcmd.CommandText = sqlQuery;
