                    sqlQuery = $"insert into POI_TEXT(id, poi_id, descrizione_breve, descrizione, lingua_id, attivo, mod_dte, uuid) values(2018924, 2018924, 'L’asd bike monti azzurri nasce nel 2010 da un gruppo di amici di Caldarola e dintorni che hanno in comune le stesse passioni, ovvero la MTB e la montagna.', 'NULL', 1, 'Y', DATETIME(datetime('now', 'localtime')), '{Guid.NewGuid()}') ";
